template <typename T>
struct is_fundamental_int : std::false_type {};

// Full Specialization: Standard int
template <>
struct is_fundamental_int<int> : std::true_type {};

// Full Specialization: Standard long
template <>
struct is_fundamental_int<long> : std::true_type {};

// Partial Specialization: const types
template <typename T>
struct is_fundamental_int<const T> : is_fundamental_int<T> {};

// C++17 Variable Template (Helper alias)
template <typename T>
inline constexpr bool is_fundamental_int_v =
    is_fundamental_int<T>::value;

struct MyType {};

constexpr bool R1 = is_fundamental_int_v<int>;      // true
constexpr bool R2 = is_fundamental_int_v<const long>; // true
constexpr bool R3 = is_fundamental_int_v<MyType>;   // false
